//! TACOT 3.0, locked in: every number the slab solver knows about the material.
//!
//! TACOT is a made-up material of the same family as low-density
//! carbon/phenolic heat-shield materials. It is not PICA.
//!
//! Source of every number: `TACOT_3.0.xls` by Lachaud, van Eekelen, Bianchi
//! and Martin (<https://jeanlachaud.com/research/TACOT_3.0.xls>, read
//! 2026-10-09), through its transcription, sheet by sheet, into these
//! tables:
//!
//! - `tacot_virgin_thermal.csv`, `tacot_char_thermal.csv` (sheet "Thermal
//!   Properties"): specific heat, conductivity and emissivity of virgin and of
//!   char, and the two enthalpies at 298 K;
//! - `tacot_decomposition_reactions.csv`, `tacot_constants.csv` (sheet
//!   "Pyrolysis model"): the two resin parts and the volume fractions;
//! - `tacot_pyrolysis_gas_equilibrium_1atm.csv` (same sheet): enthalpy of the
//!   decomposition gas in chemical equilibrium at 1 atm;
//! - `tacot_bprime_table_air.csv` (sheet "B' table"): the surface table in
//!   air, 15,100 nodes.
//!
//! This file holds data only. A second material is a second file like this
//! one, ending in its own [`Material`].

use crate::ablator_slab::{Material, ResinPart, SurfaceTable};

