// ---------------------------------------------------------------------------
// The surface table in air.
//
// Chemical equilibrium at the wall between the gas arriving from the stream
// (air, O2/N2 = 0.21/0.79 by mole), the decomposition gas and solid carbon,
// all species diffusing alike; 25 gas species. For each wall pressure,
// each B'g (decomposition-gas flux over the blown transfer coefficient) and
// each wall temperature it gives B'c (char consumed over the same
// coefficient) and the enthalpy of the gas mixture at the wall.
//
// Above the temperature at which carbon boils at a given pressure the sheet
// repeats its last B'c. Those repeated nodes are a cap, not a value: the
// solver finds them and refuses a face that hot.
// ---------------------------------------------------------------------------

